package com.bytbeat.dayplan;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.net.Uri;
import android.os.Build;
import org.json.*;
import java.time.*;
import java.util.*;
public final class ReminderScheduler {
    private static final String PREF="planner_reminders",KEY="rules",CHANNEL="planner_events_v1";
    static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences(PREF,Context.MODE_PRIVATE);}
    static JSONArray rules(Context c){try{return new JSONArray(prefs(c).getString(KEY,"[]"));}catch(Exception e){return new JSONArray();}}
    public static boolean notificationsAllowed(Context c){NotificationManager nm=c.getSystemService(NotificationManager.class);return nm.areNotificationsEnabled()&&(Build.VERSION.SDK_INT<33||c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED);}
    public static boolean exactAllowed(Context c){return Build.VERSION.SDK_INT<31||c.getSystemService(AlarmManager.class).canScheduleExactAlarms();}
    public static void channel(Context c){NotificationChannel ch=new NotificationChannel(CHANNEL,"Дела и события",NotificationManager.IMPORTANCE_HIGH);ch.setDescription("Напоминания расписания и личных событий");ch.enableVibration(true);c.getSystemService(NotificationManager.class).createNotificationChannel(ch);}
    static int number(Context c,String id){String key="id:"+id;int n=prefs(c).getInt(key,0);if(n!=0)return n;n=prefs(c).getInt("counter",1000)+1;prefs(c).edit().putInt(key,n).putInt("counter",n).apply();return n;}
    static PendingIntent alarmIntent(Context c,JSONObject r,ReminderTime.Occurrence o){String id=r.optString("id");Intent i=new Intent(c,ReminderReceiver.class).setAction("com.bytbeat.dayplan.REMIND").setData(Uri.parse("dayplan://alarm/"+Uri.encode(id))).putExtra("id",id);if(o!=null)i.putExtra("event",o.eventMillis);return PendingIntent.getBroadcast(c,number(c,id),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    static boolean valid(JSONObject r){try{if(r.getString("id").isEmpty()||r.getString("id").length()>150||r.getString("title").trim().isEmpty()||r.getString("title").length()>500)return false;LocalDate.parse(r.getString("date"));LocalTime.parse(r.getString("time"));String repeat=r.getString("repeat");if(!Arrays.asList("none","daily","weekly","monthly","yearly").contains(repeat))return false;int lead=r.getInt("lead");if(lead<0||lead>10080)return false;JSONArray days=r.getJSONArray("days");if(days.length()>7||("weekly".equals(repeat)&&days.length()==0))return false;for(int i=0;i<days.length();i++)if(days.getInt(i)<1||days.getInt(i)>7)return false;r.getBoolean("enabled");return true;}catch(Exception e){return false;}}
    public static synchronized boolean sync(Context c,String json){try{JSONArray next=new JSONArray(json);if(next.length()>500)return false;Set<String> ids=new HashSet<>();for(int i=0;i<next.length();i++){JSONObject r=next.getJSONObject(i);if(!valid(r)||!ids.add(r.getString("id")))return false;}AlarmManager am=c.getSystemService(AlarmManager.class);JSONArray old=rules(c);for(int i=0;i<old.length();i++)am.cancel(alarmIntent(c,old.getJSONObject(i),null));prefs(c).edit().putString(KEY,next.toString()).commit();restore(c);return true;}catch(Exception e){return false;}}
    static void schedule(Context c,JSONObject r,long after){if(!r.optBoolean("enabled"))return;try{Set<Integer> days=new HashSet<>();JSONArray a=r.getJSONArray("days");for(int i=0;i<a.length();i++)days.add(a.getInt(i));ReminderTime.Occurrence o=ReminderTime.next(LocalDate.parse(r.getString("date")),LocalTime.parse(r.getString("time")),r.getString("repeat"),days,r.getInt("lead"),ZoneId.systemDefault(),after);if(o==null)return;AlarmManager am=c.getSystemService(AlarmManager.class);PendingIntent pi=alarmIntent(c,r,o);try{if(exactAllowed(c))am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,o.triggerMillis,pi);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,o.triggerMillis,pi);}catch(SecurityException e){am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,o.triggerMillis,pi);}}catch(Exception e){}}
    public static synchronized void restore(Context c){channel(c);JSONArray a=rules(c);for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);if(r!=null&&valid(r))schedule(c,r,System.currentTimeMillis());}}
    public static void fire(Context c,String id,long event){JSONArray a=rules(c);for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);if(r==null||!r.optString("id").equals(id)||!r.optBoolean("enabled"))continue;String date=Instant.ofEpochMilli(event).atZone(ZoneId.systemDefault()).toLocalDate().toString();notify(c,id,r.optString("title"),"Запланировано на "+r.optString("time"),date);schedule(c,r,System.currentTimeMillis()+1000);return;}}
    public static void notify(Context c,String id,String title,String body,String date){channel(c);if(!notificationsAllowed(c))return;Intent open=new Intent(c,PlannerActivity.class).setAction("com.bytbeat.dayplan.OPEN_REMINDER").setData(Uri.parse("dayplan://event/"+Uri.encode(id))).putExtra("openDate",date).putExtra("openReminderId",id).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent tap=PendingIntent.getActivity(c,number(c,"tap:"+id),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(c,CHANNEL).setSmallIcon(com.bytbeat.dayplan.R.drawable.ic_notification).setContentTitle(title).setContentText(body).setStyle(new Notification.BigTextStyle().bigText(body)).setContentIntent(tap).setAutoCancel(true).setCategory(Notification.CATEGORY_REMINDER).setVisibility(Notification.VISIBILITY_PRIVATE).build();c.getSystemService(NotificationManager.class).notify(number(c,id),n);}
}
